begin;
with j as (select * from jsonb_to_recordset($law7d0057$[{"code_id":"NK_RF","article_number":"25.14","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n1. Налогоплательщики, признаваемые налоговыми резидентами Российской Федерации, в случаях и порядке, предусмотренных настоящим Кодексом, уведомляют налоговый орган:\n\n1) о своем участии в иностранных организациях (об учреждении иностранных структур без образования юридического лица);\n\n2) о контролируемых иностранных компаниях, контролирующими лицами которых они являются.\n\n2. Если иное не предусмотрено настоящей статьей, уведомление о контролируемых иностранных компаниях представляется:\n\nналогоплательщиками-организациями в срок не позднее 20 марта года, следующего за налоговым периодом, в котором контролирующим лицом признается доход в виде прибыли контролируемой иностранной компании в соответствии с главой 25 настоящего Кодекса либо который следует за годом, по итогам которого определен убыток контролируемой иностранной компании;\n\nналогоплательщиками - физическими лицами в срок не позднее 30 апреля года, следующего за налоговым периодом, в котором контролирующим лицом признается доход в виде прибыли контролируемой иностранной компании в соответствии с главой 23 настоящего Кодекса либо который следует за годом, по итогам которого определен убыток контролируемой иностранной компании.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n3. Если иное не предусмотрено настоящей статьей, уведомление об участии в иностранных организациях (об учреждении иностранных структур без образования юридического лица) (далее в настоящем\n\nКодексе - уведомление об участии в иностранных организациях) представляется в срок не позднее трех месяцев с даты возникновения (изменения доли) участия в такой иностранной организации (даты учреждения иностранной структуры без образования юридического лица), являющегося основанием для представления такого уведомления, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 19.02.2018 № 34-ФЗ)\n\nЕсли физическое лицо, не являвшееся налоговым резидентом Российской Федерации в момент возникновения оснований для представления уведомления об участии в иностранных организациях, указанных в абзаце первом настоящего пункта, признается налоговым резидентом Российской Федерации по итогам этого календарного года, то уведомление об участии в иностранных организациях представляется таким физическим лицом в срок не позднее 1 марта года, следующего за указанным календарным годом. Указанное уведомление представляется физическим лицом при наличии у него на 31 декабря календарного года, по итогам которого такое физическое лицо признается налоговым резидентом Российской Федерации, доли участия в иностранной организации, размер которой превышает размер, установленный подпунктом 1 пункта 31 статьи 23 настоящего Кодекса, либо при наличии учрежденной (зарегистрированной) таким физическим лицом на указанную дату иностранной структуры без образования юридического лица. Сведения и информация, предусмотренные пунктом 5 настоящей статьи, указываются в уведомлении об участии в иностранных организациях по состоянию на 31 декабря соответствующего календарного года.\n\nДля целей представления уведомления об участии в иностранных организациях в связи с изменением доли участия в иностранной организации применяется значение изменения доли участия в такой иностранной организации с точностью до двух знаков после запятой, при этом округление второго знака после запятой производится по правилам математического округления. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nВ случае, если после представления уведомления об участии в иностранных организациях основания для представления такого уведомления не изменились, повторные уведомления не представляются.\n\nВ случае прекращения участия в иностранных организациях (прекращения (ликвидации) иностранных структур без образования юридического лица) налогоплательщик информирует об этом налоговый орган в срок не позднее трех месяцев с даты прекращения участия (с указанием даты окончания участия в иностранной организации (даты прекращения (ликвидации) иностранной структуры без образования юридического лица).\n\nПоложения настоящего пункта не распространяются на налогоплательщиков, участие которых в иностранных организациях реализовано исключительно через прямое и (или) косвенное участие в одной или нескольких публичных компаниях, являющихся российскими организациями. Освобождение от применения положений настоящего пункта, установленное настоящим абзацем, не применяется при представлении уведомления об участии в иностранных организациях за периоды до 1 января 2029 года в случае, если участие налогоплательщиков в иностранных организациях реализовано исключительно через прямое и (или) косвенное участие в одной или нескольких публичных компаниях, признаваемых международными холдинговыми компаниями в соответствии со статьей 242 настоящего Кодекса. (В редакции Федерального закона от 03.08.2018 № 294-ФЗ)\n\nМеждународная компания в течение одного месяца со дня ее регистрации представляет уведомление об участии в иностранных организациях в отношении долей участия в иностранных организациях (учреждения иностранных структур без образования юридического лица) по состоянию на дату государственной регистрации такой международной компании. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 294-ФЗ)\n\nЕсли в отношении иностранной организации или налогоплательщика, являющегося контролирующим лицом указанной иностранной организации, действуют введенные иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, приводящие к введению принудительного внешнего управления над иностранной организацией, налогоплательщик вправе уведомить налоговый орган о прекращении участия в указанной иностранной организации. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n4. Налогоплательщики представляют уведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях в налоговый орган по месту своего нахождения (месту жительства).\n\nНалогоплательщики, отнесенные в соответствии со статьей 83 настоящего Кодекса к категории крупнейших налогоплательщиков, представляют уведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях в налоговый орган по месту своего учета в качестве крупнейших налогоплательщиков.\n\nУведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях представляются в налоговый орган налогоплательщиками по установленным формам (форматам) в электронной форме. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nНалогоплательщики - физические лица вправе представить указанные уведомления на бумажном носителе.\n\nФормы (форматы) уведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях, а также порядок заполнения форм и порядок представления уведомления об участии в иностранных организациях и о контролируемых иностранных компаниях в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Министерством финансов Российской Федерации. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n5. В уведомлении об участии в иностранных организациях указываются следующие сведения и информация:\n\n1) дата возникновения основания для представления уведомления;\n\n2) наименование иностранной организации (иностранной структуры без образования юридического лица), уведомление об участии в которой (об учреждении которой) представлено налогоплательщиком;\n\n3) регистрационный номер (номера), присвоенный иностранной организации в государстве (на территории) ее регистрации (инкорпорации), код (коды) иностранной организации в качестве налогоплательщика в государстве (на территории) ее регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) иностранной организации при их наличии;\n\n4) организационная форма иностранной структуры без образования юридического лица, наименование и реквизиты документа об учреждении иностранной структуры без образования юридического лица, дата учреждения (регистрации) иностранной структуры без образования юридического лица, регистрационный номер (иной идентификатор) в государстве учреждения (регистрации) иностранной структуры без образования юридического лица при их наличии (или их аналоги);\n\n5) доля участия налогоплательщика в иностранной организации, раскрытие порядка участия налогоплательщика в иностранной организации при наличии косвенного участия, в том числе через российскую организацию и (или) с использованием иностранной структуры без образования юридического лица, в случае, если налогоплательщик признается контролирующим лицом такой иностранной структуры без образования юридического лица, с указанием следующих сведений:\n\nсведения, предусмотренные подпунктами 2, 3 и 4 настоящего пункта, - в отношении каждой последующей организации (иностранной структуры без образования юридического лица), через которую (с использованием которой) реализовано косвенное участие в иностранной организации;\n\nдоля участия в каждой последующей организации, через которую реализовано косвенное участие в иностранной организации;\n\nнаименование, основной государственный регистрационный номер, идентификационный номер налогоплательщика, код причины постановки на учет налогоплательщика - российской организации, через которую реализовано косвенное участие в иностранной организации;\n\n6) информация о том, является ли налогоплательщик - учредитель (основатель) иностранной структуры без образования юридического лица контролирующим лицом такой структуры (в случае, если уведомление представляется налогоплательщиком в отношении учрежденной им иностранной структуры без образования юридического лица).\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n6. В уведомлении о контролируемых иностранных компаниях указываются следующие сведения и информация:\n\n1) период, за который представляется уведомление;\n\n11) дата представления в налоговый орган уведомления о переходе на уплату налога на доходы физических лиц с фиксированной прибыли (при наличии); (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n12) дата представления в налоговый орган уведомления об отказе от уплаты налога на доходы физических лиц с фиксированной прибыли (при наличии); (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n2) наименование иностранной организации (иностранной структуры без образования юридического лица), уведомление об участии в которой (об учреждении которой) представлено налогоплательщиком;\n\n3) регистрационный номер (номера), присвоенный иностранной организации в государстве (на территории) ее регистрации (инкорпорации), код (коды) иностранной организации в качестве налогоплательщика в государстве (на территории) ее регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) иностранной организации при их наличии;\n\n4) организационная форма иностранной структуры без образования юридического лица, наименование и реквизиты документа об учреждении иностранной структуры без образования юридического лица, дата учреждения (регистрации) иностранной структуры без образования юридического лица, регистрационный номер (иной идентификатор) в государстве учреждения (регистрации) иностранной структуры без образования юридического лица при их наличии (или их аналоги);\n\n5) дата, являющаяся последним днем периода, за который составляется финансовая отчетность организации (иностранной структуры без образования юридического лица) за финансовый год в соответствии с ее личным законом;\n\n6) дата составления финансовой отчетности организации (иностранной структуры без образования юридического лица) за финансовый год в соответствии с ее личным законом;\n\n7) дата составления аудиторского заключения по финансовой отчетности иностранной организации (иностранной структуры без образования юридического лица) за финансовый год (если в соответствии с личным законом или учредительными (корпоративными) документами этой иностранной организации (иностранной структуры без образования юридического лица) установлено обязательное проведение аудита такой финансовой отчетности или такой аудит осуществляется иностранной организацией (иностранной структурой без образования юридического лица) добровольно);\n\n8) доля участия налогоплательщика в иностранной организации, раскрытие порядка участия налогоплательщика в иностранной организации при наличии косвенного участия, в том числе через российскую организацию и (или) с использованием иностранной структуры без образования юридического лица, в случае, если налогоплательщик признается контролирующим лицом такой иностранной структуры без образования юридического лица, с указанием следующих сведений:\n\nсведения, предусмотренные подпунктами 2, 3 и 4 настоящего пункта, - в отношении каждой последующей организации (иностранной структуры без образования юридического лица), через которую (с использованием которой) реализовано косвенное участие в иностранной организации;\n\nнаименование, основной государственный регистрационный номер, идентификационный номер налогоплательщика, код причины постановки на учет налогоплательщика - российской организации, через которую реализовано косвенное участие в иностранной организации;\n\nдоля участия в каждой последующей организации, через которую реализовано косвенное участие в иностранной организации;\n\n9) описание оснований для признания налогоплательщика контролирующим лицом иностранной компании;\n\n10) описание оснований для освобождения прибыли контролируемой иностранной компании от налогообложения в соответствии с настоящим Кодексом.\n\nВ случае, если налогоплательщик воспользовался правом не представлять документы, предусмотренные пунктом 9 статьи 2513-1 настоящего Кодекса, в уведомлении о контролируемых иностранных компаниях при раскрытии информации, предусмотренной подпунктом 8 настоящего пункта, отражается информация о налогоплательщике - контролирующем лице, являющемся российской организацией, через которую реализовано косвенное участие налогоплательщика в контролируемой иностранной компании, представившем документы, предусмотренные пунктом 9 статьи 2513-1 настоящего Кодекса;\n\n(Подпункт в редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n11) о соблюдении условий освобождения от применения положений статьи 2515 настоящего Кодекса в отношении прибыли контролируемой иностранной компании в соответствии с пунктом 81 статьи 2515 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n7. В случае обнаружения неполноты сведений, неточностей либо ошибок в заполнении представленного уведомления об участии в иностранных организациях или уведомления о контролируемых иностранных компаниях налогоплательщик вправе представить уточненное уведомление.\n\nВ случае подачи уточненного уведомления до момента, когда налогоплательщик узнал об установлении налоговым органом факта отражения в уведомлении недостоверных сведений, налогоплательщик освобождается от ответственности, предусмотренной статьей 1296 настоящего Кодекса.\n\n1) наименование (фамилия, имя, отчество) налогоплательщика, которому направляется требование; (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n2) наименование иностранных организаций (иностранных структур без образования юридического лица), в отношении которых у налогового органа имеется информация, свидетельствующая о том, что налогоплательщик является их контролирующим лицом;\n\n3) регистрационный номер (номера), присвоенный иностранной организации (иностранной структуре без образования юридического лица), в отношении которой у налогового органа имеется информация, свидетельствующая о том, что налогоплательщик является ее контролирующим лицом; (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n4) описание оснований, имеющихся у налогового органа, для признания налогоплательщика контролирующим лицом иностранной организации (иностранной структуры без образования юридического лица);\n\n5) период, за который налогоплательщику необходимо представить уведомление, предусмотренное пунктом 6 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\nВ случае признания налогоплательщика контролирующим лицом на основании подпункта 2 пункта 3 статьи 2513 настоящего Кодекса налогоплательщик вправе представить в налоговый орган одновременно с уведомлением о контролируемых иностранных компаниях соответствующие пояснения и (или) документы, подтверждающие, что ему не было известно о том, что в календарном году, за который не было представлено уведомление о контролируемых иностранных компаниях, доля участия в иностранной организации всех лиц, признаваемых налоговыми резидентами Российской Федерации (для физических лиц - совместно с супругами и несовершеннолетними детьми), составляла более 50 процентов.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nНалогоплательщик, признаваемый контролирующим лицом на основании подпункта 2 пункта 3 статьи 2513 настоящего Кодекса, освобождается от ответственности, предусмотренной статьями 1295 и 1296 настоящего Кодекса, в случае представления в установленный налоговым органом срок уведомления о контролируемых иностранных компаниях, информация о которых содержится в требовании. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nзации, в порядке редомициляции которой зарегистрирована международная компания, освобождается от ответственности, предусмотренной статьей 1296 настоящего Кодекса за непредставление уведомления о контролируемых иностранных компаниях, в случае, если такая иностранная организация в соответствии с ее личным законом признается фактически прекратившей свою деятельность (недействующим юридическим лицом).\n\nДля применения положений настоящего пункта налогоплательщик представляет документы, подтверждающие признание указанной в абзаце первом настоящего пункта иностранной организации в соответствии с ее личным законом фактически прекратившей свою деятельность (недействующим юридическим лицом). Такие документы представляются в срок, предусмотренный пунктом 2 настоящей статьи, и подлежат переводу на русский язык в части, необходимой для подтверждения соблюдения условия применения положений настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 595-ФЗ)","article_title":"Статья 25.14. Уведомление об участии в иностранных организациях и уведомление о контролируемых иностранных компаниях. Порядок признания налогоплательщиков контролирующими лицами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ea8538d76de7f51b28b87659b1bf4911889228dfa5b075ab3e02541e77d1c99"},{"code_id":"NK_RF","article_number":"25.14-1","version_date":"2000-07-31","article_text":"Предусмотренные настоящим пунктом документы не могут быть истребованы у налогоплательщика - контролирующего лица, являющегося физическим лицом, который представил в налоговый орган уведомление о переходе на уплату налога на доходы физических лиц с фиксированной прибыли в порядке и на условиях, которые установлены главой 23 настоящего Кодекса, если указанные документы относятся к налоговым периодам, в течение которых таким налогоплательщиком применялся установленный статьей 2272 настоящего Кодекса порядок уплаты налога на доходы физических лиц с фиксированной прибыли.\n\nНалоговый орган вправе истребовать у налогоплательщика - контролирующего лица документы, относящиеся к налоговым периодам, предшествующим году направления требования, но не более чем за три календарных года.\n\n(Дополнение статьей - Федеральный закон от 09.11.2020 № 368-ФЗ)","article_title":"Статья 25.14-1. Истребование у налогоплательщиков - контролирующих лиц документов в отношении контролируемых ими иностранных компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b0765dc847dd35f9ddbf174e2f59f25a0838d5cafceb8260f8a99edcabbbb957"},{"code_id":"NK_RF","article_number":"25.15","version_date":"2000-07-31","article_text":"1. Прибылью (убытком) контролируемой иностранной компании в целях настоящего Кодекса признается сумма прибыли (убытка) этой компании, рассчитанная в соответствии со статьей 3091 настоящего Кодекса.\n\nПрибыль контролируемой иностранной компании уменьшается на величину дивидендов, выплаченных этой иностранной компанией в календарном году, следующем за годом, за который в соответствии с личным законом такой компании составляется финансовая отчетность, с учетом промежуточных дивидендов, выплаченных в течение финансового года, за который составляется эта финансовая отчетность, с учетом особенностей, предусмотренных статьей 3091 настоящего Кодекса. В случае, если финансовая отчетность компании в соответствии с ее личным законом не составляется, для целей настоящего абзаца применяется календарный год.\n\nПри определении прибыли контролируемой иностранной компании не учитываются доходы, указанные в пункте 1 статьи 309 настоящего Кодекса, источником выплаты которых являются российские организации, если контролирующее лицо этой контролируемой иностранной компании имеет фактическое право на такие доходы с учетом положений статьи 312 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nПрибыль контролируемой иностранной компании, являющейся иностранной структурой без образования юридического лица или иностранным юридическим лицом, для которого в соответствии с его личным законом не предусмотрено участие в капитале, уменьшается на величину распределенной прибыли. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n(Пункт в редакции Федерального закона от 08.06.2015 № 150-ФЗ)\n\n11. При определении прибыли контролируемой иностранной компании, являющейся структурой без образования юридического лица, не учитываются доходы в виде имущества (включая денежные средства) и (или) имущественных прав, которые получены в качестве взноса (вклада) от учредителя (основателя) данной структуры и (или) лиц, являющихся членами его семьи и (или) близкими родственниками в соответствии с Семейным кодексом Российской Федерации (супругами, родителями и детьми, в том числе усыновителями и усыновленными, дедушками, бабушками и внуками, полнородными и неполнородными (имеющими общих отца или мать) братьями и сестрами), а также от иной контролируемой иностранной компании (в том числе иностранной структуры без образования юридического лица), в отношении которой хотя бы одно из указанных выше лиц является контролирующим лицом. При этом, если передающая сторона является контролируемой иностранной компанией, при определении прибыли этой контролируемой иностранной компании не учитываются расходы в виде переданного имущества (включая денежные средства) и (или) имущественных прав.\n\nПоложения настоящего пункта не применяются при передаче имущества и (или) имущественных прав контролируемой иностранной компанией (получении имущества и (или) имущественных прав от контролируемой иностранной компании), источником формирования которых являлась прибыль передающей стороны за финансовый год, в котором осуществлена ее ликвидация (прекращение).\n\nВ целях настоящего пункта к иностранным структурам без образования юридического лица приравниваются иностранные юридические лица, для которых в соответствии с их личным законом не предусмотрено участие в капитале.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\n12. В целях осуществления корректировок прибыли контролируемой иностранной компании, предусмотренных абзацами вторым и четвертым пункта 1 настоящей статьи, налогоплательщик - контролирующее лицо, являющийся российской организацией, вправе учесть вместо величины дивидендов (распределенной прибыли), указанных в абзаце втором или четвертом пункта 1 настоящей статьи, величину, равную сумме прибыли указанной компании, рассчитанной в соответствии со статьей 3091 настоящего Кодекса, если указанная компания одновременно удовлетворяет всем следующим условиям:\n\n1) в отношении такого налогоплательщика и (или) указанной компании либо в отношении иной контролируемой налогоплательщиком иностранной компании, являющейся акционером (участником) указанной компании, по состоянию на дату окончания календарного года, следующего за годом, за который составляется финансовая отчетность, действовали введенные иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на проведение расчетов и (или) осуществление (исполнение) операций (сделок) и препятствующие принятию решений о распределении прибыли, объявлению и (или) осуществлению выплаты дивидендов (распределенной прибыли) указанной компанией и (или) иной контролируемой налогоплательщиком иностранной компанией, являющейся акционером (участником) указанной компании;\n\n2) выплата соответствующих дивидендов (распределенной прибыли) (в том числе в неденежной форме) указанной компанией по состоянию на дату окончания календарного года, следующего за годом, за который составляется финансовая отчетность, не производилась;\n\n3) государство (территория) постоянного места нахождения указанной компании не включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны), если иное не предусмотрено законодательством о налогах и сборах. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\nВ случае прекращения выполнения хотя бы одного из условий, установленных пунктом 12 настоящей статьи в отношении контролируемой иностранной компании, суммы прибыли указанной иностранной компании, которые ранее не были учтены при определении налоговой базы у налогоплательщика - контролирующего лица в результате применения положений пункта 12 настоящей статьи, подлежат учету при определении налоговой базы такого налогоплательщика за налоговый период, в котором перестало выполняться соответствующее условие (а в случае прекращения выполнения условия, указанного в подпункте 1 пункта 12 настоящей статьи, в период с 1 октября по 31 декабря за налоговый период, следующий за годом, в котором перестало выполняться это условие), в порядке, предусмотренном главой 25 настоящего Кодекса, с учетом особенностей, установленных настоящей статьей. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nВ случае утраты налогоплательщиком, указанным в абзаце первом пункта 12 настоящей статьи, статуса контролирующего лица (за исключением случаев утраты такого статуса в результате введенных иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями мер ограничительного характера, заключающихся в лишении указанного налогоплательщика прав на прибыль (доходы) и имущество контролируемой иностранной компании) либо в случае принятия решения о ликвидации указанного налогоплательщика или контролируемой иностранной компании (за исключением случаев ликвидации контролируемой иностранной компании в результате введенных иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями мер ограничительного характера, заключающихся в лишении указанного налогоплательщика прав на прибыль (доходы) и имущество контролируемой иностранной компании) суммы прибыли, которые ранее не были учтены при определении налоговой базы у указанного налогоплательщика в результате применения положений настоящего пункта, подлежат учету при определении налоговой базы такого налогоплательщика за налоговый период, в котором произошла утрата статуса контролирующего лица либо принято решение о ликвидации, в порядке, предусмотренном главой 25 настоящего Кодекса, с учетом особенностей, установленных настоящей статьей. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n2. Прибыль контролируемой иностранной компании, определяемая в соответствии с настоящим Кодексом, приравнивается к прибыли организации (доходу физических лиц) (далее в настоящей главе - прибыль и доход соответственно), полученной налогоплательщиком, признаваемым контролирующим лицом этой контролируемой иностранной компании, и учитывается при определении налоговой базы по налогам у налогоплательщиков, признаваемых контролирующими лицами этой контролируемой иностранной компании в соответствии с главами части второй настоящего Кодекса с учетом особенностей, установленных настоящей статьей.\n\nПри невозможности определения доли прибыли контролируемой иностранной компании в соответствии с абзацем первым настоящего пункта прибыль такой контролируемой иностранной компании учитывается при определении налоговой базы у налогоплательщика - контролирующего лица исходя из суммы прибыли, на которую имеет (будет иметь) право налогоплательщик в случае ее распределения между лицами, которые обладают фактическим правом на такую прибыль. При этом такая сумма прибыли определяется на 31 декабря календарного года, следующего за налоговым периодом по соответствующему налогу для налогоплательщика - контролирующего лица, на который приходится дата окончания финансового года контролируемой иностранной компании. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nВ случае, если доля участия налогоплательщика - контролирующего лица в контролируемой иностранной организации отличается от доли в прибыли, на которую налогоплательщик в случае ее распределения имеет право (в соответствии с ее личным законом, уставными документами либо соглашением между ее акционерами (участниками), прибыль контролируемой иностранной компании учитывается при определении налоговой базы у налогоплательщика - контролирующего лица в доле, соответствующей доле в прибыли контролируемой иностранной компании, на которую это лицо имеет право на дату принятия решения о распределении прибыли, принятого в календарном году, следующем за налоговым периодом по соответствующему налогу для налогоплательщика - контролирующего лица, на который приходится дата окончания финансового года в соответствии с личным законом этой контролируемой иностранной компании, а в случае, если такое решение не принято, то на 31 декабря календарного года, следующего за налоговым периодом по соответствующему налогу для налогоплательщика - контролирующего лица, на который приходится дата окончания финансового года контролируемой иностранной компании. (Дополнение абзацем - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\nПри этом если в результате применения абзаца первого настоящего пункта сумма прибыли контролируемой иностранной компании, подлежащая учету при определении налоговой базы у налогоплательщика - контролирующего лица, равна нулю, налогоплательщик вправе не отражать такой результат и сведения о такой контролируемой иностранной компании в налоговой декларации по налогу на прибыль организаций (налогу на доходы физических лиц). (В редакции федеральных законов от 15.02.2016 № 32-ФЗ; от 28.12.2017 № 436-ФЗ)\n\n1) финансовая отчетность контролируемой иностранной компании, составленная в соответствии с личным законом такой компании за финансовый год, или в случае отсутствия финансовой отчетности иные документы, подтверждающие прибыль (убыток) такой компании за финансовый год;\n\n2) аудиторское заключение по финансовой отчетности контролируемой иностранной компании, указанной в подпункте 1 настоящего пункта, если в соответствии с личным законом или учредительными (корпоративными) документами этой контролируемой иностранной компании установлено обязательное проведение аудита такой финансовой отчетности или аудит осуществляется иностранной организацией добровольно.\n\nУказанные в настоящем пункте документы представляются независимо от наличия обязанности по учету дохода в виде прибыли контролируемой иностранной компании в налоговой базе контролирующего лица по соответствующему налогу в следующие сроки:\n\nналогоплательщиками-организациями вместе с налоговой декларацией по налогу на прибыль организаций;\n\nналогоплательщиками - физическими лицами вместе с уведомлением о контролируемых иностранных компаниях.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nпункте 5 настоящей статьи, составленные на иностранном языке, должны быть переведены на русский язык.\n\nВ случае невозможности представления аудиторского заключения по финансовой отчетности одновременно с представлением налоговой декларации в соответствии с пунктом 5 настоящей статьи указанное аудиторское заключение представляется в срок не позднее одного месяца со дня, отраженного в уведомлении о контролируемых иностранных компаниях в качестве даты составления аудиторского заключения по финансовой отчетности.\n\n1) указанная структура в соответствии со своим личным законом является формой осуществления коллективных инвестиций;\n\n2) прибыль (доходы) указанной структуры в соответствии с ее личным законом не подлежит налогообложению;\n\n3) распределенная указанной структурой прибыль (выплаченные ею доходы) в пользу своих участников (пайщиков и иных лиц) либо бенефициаров подлежит учету при определении налоговой базы по налогам у налогоплательщиков, признаваемых контролирующими лицами этой структуры, в соответствии с главами части второй настоящего Кодекса.\n\nВ целях предусмотренного настоящим пунктом освобождения от применения положений настоящей статьи в отношении прибыли контролируемой иностранной компании налогоплательщик - контролирующее лицо представляет в налоговый орган по месту своего нахождения документы, подтверждающие соблюдение условий для такого освобождения. Указанные документы представляются в срок, предусмотренный пунктом 2 статьи 2514 настоящего Кодекса, и подлежат переводу на русский язык в части, необходимой для подтверждения соблюдения условий для освобождения от применения положений настоящей статьи в отношении прибыли контролируемой иностранной компании в соответствии с настоящим пунктом.\n\nНалогоплательщик - контролирующее лицо вправе не представлять документы, предусмотренные настоящим пунктом, если такие документы были представлены иным налогоплательщиком - контролирующим лицом этой контролируемой иностранной компании, являющимся российской организацией, через которую реализовано косвенное участие налогоплательщика, использующего право, предусмотренное настоящим абзацем, в такой контролируемой иностранной компании. Налогоплательщик - контролирующее лицо может воспользоваться данным правом при условии указания им в уведомлении о контролируемых иностранных компаниях, представляемом в соответствии с пунктом 2 статьи 2514 настоящего Кодекса, сведений об организации, представившей документы, предусмотренные настоящим пунктом.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение главой - Федеральный закон от 02.08.2019 № 269-ФЗ)","article_title":"Статья 25.15. Порядок учета прибыли контролируемой иностранной компании при налогообложении","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"68e00c866ad35c82f691f39e4695ca786d64ef3c4b9c55a680fcb1c28cecc083"},{"code_id":"NK_RF","article_number":"25.16","version_date":"2000-07-31","article_text":"Лицо приобретает статус налогоплательщика - участника специального инвестиционного контракта со дня включения сведений о заключении специального инвестиционного контракта в реестр специальных инвестиционных контрактов, предусмотренный пунктом 73 части 1 статьи 6 Федерального закона от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\" (далее в настоящей главе - реестр).\n\n1) прекращение действия специального инвестиционного контракта - со дня прекращения действия такого контракта;\n\n2) расторжение специального инвестиционного контракта - со дня включения сведений о расторжении специального инвестиционного контракта в реестр.\n\n(Дополнение главой - Федеральный закон от 28.06.2022 № 225-ФЗ)","article_title":"Статья 25.16. Налогоплательщики - участники специальных инвестиционных контрактов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"830cd8f0ffc29e987c50c59cd9b7507b4d71c5051c54a9451878028c8b512f92"},{"code_id":"NK_RF","article_number":"25.17","version_date":"2000-07-31","article_text":"1. Налогоплательщиком - участником соглашения о защите и поощрении капиталовложений для целей настоящего Кодекса признается организация, заключившая в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" соглашение о защите и поощрении капиталовложений, сведения о заключении которого включены в предусмотренный статьей 5 указанного Федерального закона реестр соглашений о защите и поощрении капиталовложений.\n\n2. Организация приобретает статус налогоплательщика - участника соглашения о защите и поощрении капиталовложений со дня включения сведений о заключении указанного соглашения в реестр соглашений о защите и поощрении капиталовложений.\n\n3. Организация утрачивает статус налогоплательщика - участника соглашения о защите и поощрении капиталовложений:\n\n1) с даты, с которой действие соглашения о защите и поощрении капиталовложений прекращается или считается прекратившимся, - в случае прекращения действия указанного соглашения согласно положениям Федерального закона \"О защите и поощрении капиталовложений в Российской Федерации\", если иное не установлено подпунктом 2 настоящего пункта;\n\n2) с даты получения статуса налогоплательщика - участника соглашения о защите и поощрении капиталовложений - в случае, если указанное соглашение расторгается по основаниям, предусмотренным частями 13 и 14 статьи 11 Федерального закона \"О защите и поощрении капиталовложений в Российской Федерации\", или признается недействительным в соответствии с гражданским законодательством.\n\n4. В случае утраты организацией статуса налогоплательщика - участника соглашения о защите и поощрении капиталовложений по основанию, предусмотренному подпунктом 2 пункта 3 настоящей статьи, суммы налогов (авансовых платежей по налогам), не уплаченные организацией в связи с применением положений пункта 43 статьи 5 настоящего Кодекса, а также в связи с применением такой организацией налоговых вычетов в порядке, установленном статьей 2518 настоящего Кодекса, подлежат восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих пеней.","article_title":"Статья 25.17. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"187d29fb1923db638c613f0cbf1335b0159146ddee71bdee4db61e0d08f805ee"},{"code_id":"NK_RF","article_number":"25.18","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений, одной из сторон которого является Российская Федерация, в случаях и порядке, которые предусмотрены положениями настоящей статьи и соответствующих глав части второй настоящего Кодекса, вправе уменьшать подлежащие уплате в бюджет суммы налогов (авансовых платежей по налогам) на налоговые вычеты в размере фактически осуществленных затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки (далее в целях настоящего Кодекса - налоговый вычет для СЗПК).\n\n2. В целях применения налогового вычета для СЗПК уполномоченный федеральный орган исполнительной власти, который от имени Российской Федерации подписывает соглашение о защите и поощрении капиталовложений, представляет в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомление о налоговом вычете для СЗПК. Уведомление о налоговом вычете для СЗПК должно содержать следующие сведения:\n\n1) реквизиты налогоплательщика - участника соглашения о защите и поощрении капиталовложений: полное наименование организации, адрес ее места нахождения, идентификационный номер налогоплательщика, код причины постановки на учет;\n\n2) перечень объектов учета, затраты по которым будут возмещаться за счет налогового вычета для СЗПК, формируемый раздельно по:\n\nобъектам обеспечивающей инфраструктуры, определяемым в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\";\n\nобъектам сопутствующей инфраструктуры, определяемым в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\";\n\nкредитам, займам;\n\nоблигационным займам;\n\nдемонтажу объектов, расположенных на территориях военных городков (в части жилищного строительства);\n\n3) общая сумма затрат, которые подлежат возмещению, с распределением их по объектам учета;\n\n4) распределение сумм налоговых вычетов для СЗПК по налогам с указанием срока применения налоговых вычетов для СЗПК. При этом в части налога на прибыль организаций суммы налоговых вычетов для СЗПК должны быть распределены в части налога на прибыль организаций, подлежащего зачислению в федеральный бюджет, и в части налога на прибыль организаций, зачисляемого в бюджет субъекта Российской Федерации. В части налога на имущество организаций и земельного налога суммы налоговых вычетов для СЗПК должны быть распределены по объектам налогообложения;\n\n5) кадастровые номера (при их отсутствии иные идентификационные номера, присвоенные в соответствии с законодательством Российской Федерации) объектов недвижимого имущества, в отношении которых будет применен налоговый вычет для СЗПК (если налоговый вычет для СЗПК применяется по налогу на имущество организаций);\n\n6) кадастровые номера земельных участков, в отношении которых будет применен налоговый вычет для СЗПК (если налоговый вычет для СЗПК применяется по земельному налогу).\n\n3. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в течение десяти дней со дня получения уведомления о налоговом вычете для СЗПК направляет его в налоговый орган по месту нахождения налогоплательщика - участника соглашения о защите и поощрении капиталовложений (по месту учета в качестве крупнейшего налогоплательщика).\n\n4. Форма уведомления о налоговом вычете для СЗПК и порядок ее заполнения утверждаются Правительством Российской Федерации.\n\nФормат уведомления о налоговом вычете для СЗПК и порядок его передачи в электронной форме по телекоммуникационным каналам связи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.","article_title":"Статья 25.18. Общие вопросы применения налогоплательщиком - участником соглашения о защите и поощрении капиталовложений налоговых вычетов для соглашений о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3dedae94aa4ce144014789e9daf11746eca722624452d34c2142a638d1b15152"},{"code_id":"NK_RF","article_number":"25.2","version_date":"2000-07-31","article_text":"1. Российские организации, соответствующие условиям, предусмотренным настоящей статьей, вправе создать консолидированную группу налогоплательщиков.\n\nУсловия, которым должны соответствовать участники консолидированной группы налогоплательщиков, предусмотренные настоящей статьей, применяются в течение всего срока действия договора о создании указанной группы, если иное не предусмотрено настоящим Кодексом.\n\n2. Консолидированная группа налогоплательщиков может быть создана организациями при условии, что одна организация непосредственно и (или) косвенно участвует в уставном (складочном) капитале других организаций и доля такого участия в каждой такой организации составляет не менее 90 процентов. Указанное условие должно соблюдаться в течение всего срока действия договора о создании консолидированной группы налогоплательщиков.\n\nДоля участия одной организации в другой организации определяется в порядке, установленном настоящим Кодексом.\n\n3. Организация - сторона договора о создании консолидированной группы налогоплательщиков должна соответствовать следующим условиям:\n\n1) организация не находится в процессе реорганизации или ликвидации, если иное не предусмотрено настоящим Кодексом; (В редакции Федерального закона от 28.11.2015 № 325-ФЗ)\n\n2) в отношении организации на дату регистрации договора о создании консолидированной группы налогоплательщиков либо на дату присоединения такой организации к существующей консолидированной группе налогоплательщиков не возбуждено производство по делу о несостоятельности (банкротстве); (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n21) в отношении организации не введена ни одна из процедур банкротства (за исключением наблюдения), предусмотренных законодательством Российской Федерации о несостоятельности (банкротстве); (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n3) размер чистых активов организации, рассчитанный на основании бухгалтерской (финансовой) отчетности на последнюю отчетную дату, предшествующую дате представления в налоговый орган документов для регистрации договора о создании (изменении) консолидированной группы налогоплательщиков, превышает размер ее уставного (складочного) капитала. Если на момент представления в налоговый орган договора о создании (изменении) консолидированной группы налогоплательщиков срок составления бухгалтерской (финансовой) отчетности на последнюю отчетную дату еще не наступил, то определение размера чистых активов или уставного (складочного) капитала производится на основании бухгалтерской (финансовой) отчетности, составленной на предшествующую отчетную дату. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ; от 03.08.2018 № 302-ФЗ)\n\n4. Присоединение новой организации к существующей консолидированной группе налогоплательщиков возможно при условии, что присоединяемая организация соответствует условиям, предусмотренным пунктом 3 настоящей статьи, на дату своего присоединения.\n\n5. Все в совокупности организации, являющиеся участниками консолидированной группы налогоплательщиков, должны соответствовать следующим условиям:\n\n1) совокупная сумма налога на добавленную стоимость, акцизов, налога на прибыль организаций и налога на добычу полезных ископаемых, уплаченная в течение календарного года, предшествующего году, в котором представляются в налоговый орган документы для регистрации договора о создании консолидированной группы налогоплательщиков, без учета сумм налогов, уплаченных в связи с перемещением товаров через таможенную границу Таможенного союза, составляет не менее 10 миллиардов рублей;\n\n2) суммарный объем выручки от продажи товаров, продукции, выполнения работ и оказания услуг, а также от прочих доходов по данным бухгалтерской (финансовой) отчетности за календарный год, предшествующий году, в котором представляются в налоговый орган документы для регистрации договора о создании консолидированной группы налогоплательщиков, составляет не менее 100 миллиардов рублей; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n3) совокупная стоимость активов по данным бухгалтерской (финансовой) отчетности на 31 декабря календарного года, предшествующего году, в котором представляются в налоговый орган документы для регистрации договора о создании консолидированной группы налогоплательщиков, составляет не менее 300 миллиардов рублей. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n6. Участниками консолидированной группы налогоплательщиков не могут являться следующие организации:\n\n1) организации, являющиеся резидентами особых экономических зон;\n\n2) организации, применяющие специальные налоговые режимы;\n\n3) банки, за исключением случая, когда все другие организации, входящие в эту группу, являются банками;\n\n4) страховые организации, за исключением случая, когда все другие организации, входящие в эту группу, являются страховыми организациями;\n\n5) негосударственные пенсионные фонды, за исключением случая, когда все другие организации, входящие в эту группу, являются негосударственными пенсионными фондами;\n\n6) профессиональные участники рынка ценных бумаг, не являющиеся банками, за исключением случая, когда все другие организации, входящие в эту группу, являются профессиональными участниками рынка ценных бумаг, не являющимися банками;\n\n7) организации, являющиеся участниками иной консолидированной группы налогоплательщиков;\n\n8) организации, не признаваемые налогоплательщиками налога на прибыль организаций, а также использующие право на освобождение от обязанностей налогоплательщика налога на прибыль организаций в соответствии с главой 25 настоящего Кодекса;\n\n9) организации, осуществляющие образовательную и (или) медицинскую деятельность и применяющие налоговую ставку 0 процентов по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса;\n\n10) организации, являющиеся налогоплательщиками налога на игорный бизнес;\n\n11) клиринговые организации;\n\n12) кредитные потребительские кооперативы; (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 301-ФЗ)\n\n13) микрофинансовые организации; (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 301-ФЗ)\n\n14) организации, являющиеся участниками свободной экономической зоны. (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 379-ФЗ)","article_title":"Статья 25.2. Условия создания консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20b0e0ffc39d06b21fd907ba8deeeed8338a1f98c5a0342000af9bed77d921f6"},{"code_id":"NK_RF","article_number":"25.3","version_date":"2000-07-31","article_text":"1. В соответствии с договором о создании консолидированной группы налогоплательщиков организации, соответствующие условиям, установленным статьей 252 настоящего Кодекса, объединяются на добровольной основе без создания юридического лица в целях исчисления и уплаты налога на прибыль организаций по консолидированной группе налогоплательщиков в порядке и на условиях, которые установлены настоящим Кодексом.\n\n2. Договор о создании консолидированной группы налогоплательщиков должен содержать следующие положения:\n\n1) предмет договора о создании консолидированной группы налогоплательщиков;\n\n2) перечень и реквизиты организаций - участников консолидированной группы налогоплательщиков;\n\n3) наименование организации - ответственного участника консолидированной группы налогоплательщиков;\n\n4) перечень полномочий, которые участники консолидированной группы налогоплательщиков передают ответственному участнику этой группы в соответствии с настоящей главой;\n\n5) порядок и сроки исполнения обязанностей и осуществления прав ответственным участником и другими участниками консолидированной группы налогоплательщиков, не предусмотренных настоящим Кодексом, ответственность за невыполнение установленных обязанностей;\n\n6) срок, исчисляемый в календарных годах, на который создается консолидированная группа налогоплательщиков, если она создается на определенный срок, либо указание на отсутствие определенного срока, на который создается эта группа;\n\n7) показатели, необходимые для определения налоговой базы и уплаты налога на прибыль организаций по каждому участнику консолидированной группы налогоплательщиков с учетом особенностей, предусмотренных статьей 288 настоящего Кодекса. При этом выбранные показатели не подлежат изменению в течение всего срока действия договора о создании консолидированной группы налогоплательщиков. (В редакции Федерального закона от 28.11.2015 № 325-ФЗ)\n\n3. К правоотношениям, основанным на договоре о создании консолидированной группы налогоплательщиков, применяется законодательство о налогах и сборах, а в части, не урегулированной законодательством о налогах и сборах, - гражданское законодательство Российской Федерации.\n\nЛюбые положения договора о создании консолидированной группы налогоплательщиков (включая сам такой договор), если они не соответствуют законодательству Российской Федерации, могут быть признаны недействительными в судебном порядке участником этой группы или налоговым органом.\n\n4. Договор о создании консолидированной группы налогоплательщиков действует до наступления наиболее ранней из следующих дат:\n\n1) даты прекращения действия указанного договора, предусмотренной этим договором и (или) настоящим Кодексом;\n\n2) даты расторжения договора;\n\nо числа налогового периода по налогу на прибыль организаций, следующего за датой отказа налоговым органом в регистрации указанного договора.\n\n5. Договор о создании консолидированной группы налогоплательщиков подлежит регистрации в налоговом органе по месту нахождения организации - ответственного участника консолидированной группы налогоплательщиков.\n\nВ случае, если ответственный участник консолидированной группы налогоплательщиков в соответствии со статьей 83 настоящего Кодекса отнесен к категории крупнейших налогоплательщиков, договор о создании консолидированной группы налогоплательщиков подлежит регистрации в налоговом органе по месту учета указанного ответственного участника консолидированной группы в качестве крупнейшего налогоплательщика.\n\n6. Для регистрации договора о создании консолидированной группы налогоплательщиков ответственный участник этой группы представляет в налоговый орган следующие документы:\n\n1) подписанное уполномоченными лицами всех участников создаваемой консолидированной группы заявление о регистрации договора о создании консолидированной группы налогоплательщиков;\n\n2) два экземпляра договора о создании консолидированной группы налогоплательщиков;\n\n3) документы, подтверждающие выполнение условий, предусмотренных пунктами 2, 3 и 5 статьи 252 настоящего Кодекса, заверенные ответственным участником консолидированной группы налогоплательщиков, в том числе копии платежных поручений на уплату налога на добавленную стоимость, акцизов, налога на прибыль организаций и налога на добычу полезных ископаемых (копии решений налогового органа о проведении зачета по перечисленным выше налогам), бухгалтерских балансов, отчетов о финансовых результатах за предшествующий календарный год для каждого из участников группы; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n4) документы, подтверждающие полномочия лиц, подписавших договор о создании консолидированной группы налогоплательщиков.\n\n7. Документы, указанные в пункте 6 настоящей статьи, представляются в налоговый орган не позднее 30 октября года, предшествующего налоговому периоду, начиная с которого исчисляется и уплачивается налог на прибыль организаций по консолидированной группе налогоплательщиков.\n\n8. Руководитель (заместитель руководителя) налогового органа в течение одного месяца со дня представления в налоговый орган документов, указанных в пункте 6 настоящей статьи, производит регистрацию договора о создании консолидированной группы налогоплательщиков либо принимает мотивированное решение об отказе в его регистрации.\n\nПри обнаружении нарушений, устранимых в пределах срока, установленного настоящим пунктом, налоговый орган обязан уведомить о них ответственного участника консолидированной группы налогоплательщиков.\n\nДо истечения срока, установленного настоящим пунктом, ответственный участник консолидированной группы налогоплательщиков вправе устранить выявленные нарушения.\n\n9. При соблюдении условий, предусмотренных статьей 252 настоящего Кодекса и пунктами 1 - 7 настоящей статьи, налоговый орган обязан зарегистрировать договор о создании консолидированной группы налогоплательщиков и в течение пяти дней с даты его регистрации выдать один экземпляр этого договора с отметкой о его регистрации ответственному участнику консолидированной группы налогоплательщиков лично под расписку или иным способом, свидетельствующим о дате получения.\n\nВ течение пяти дней с даты регистрации договора о создании консолидированной группы налогоплательщиков информация о регистрации договора о создании консолидированной группы налогоплательщиков направляется налоговым органом в налоговые органы по месту нахождения организаций - участников консолидированной группы налогоплательщиков, а также по месту нахождения обособленных подразделений организаций - участников консолидированной группы налогоплательщиков.\n\n10. Консолидированная группа налогоплательщиков признается созданной с 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором налоговым органом зарегистрирован договор о создании этой группы.\n\n11. Отказ налогового органа в регистрации договора о создании консолидированной группы налогоплательщиков допускается исключительно при наличии хотя бы одного из следующих обстоятельств:\n\n1) несоответствия условиям создания консолидированной группы налогоплательщиков, предусмотренным статьей 252 настоящего Кодекса;\n\n2) несоответствия договора о создании консолидированной группы налогоплательщиков требованиям, указанным в пункте 2 настоящей статьи;\n\n3) непредставления (представления не в полном объеме) или нарушения срока представления в уполномоченный налоговый орган документов для регистрации договора о создании консолидированной группы налогоплательщиков, предусмотренных пунктами 5 - 7 настоящей статьи;\n\n4) в случае подписания документов не уполномоченными на это лицами.\n\n12. В случае отказа налогового органа в регистрации договора о создании консолидированной группы налогоплательщиков ответственный участник консолидированной группы налогоплательщиков вправе повторно представить документы о регистрации такого договора.\n\n13. Копия решения об отказе в регистрации договора о создании консолидированной группы налогоплательщиков в течение пяти дней со дня его принятия передается налоговым органом уполномоченному представителю лица, указанного в таком договоре в качестве ответственного участника консолидированной группы налогоплательщиков, лично под расписку или иным способом, свидетельствующим о дате получения.\n\n14. Отказ в регистрации договора о создании консолидированной группы налогоплательщиков может быть обжалован лицом, указанным в таком договоре в качестве ответственного участника консолидированной группы налогоплательщиков, в порядке и сроки, которые установлены настоящим Кодексом для обжалования актов, действий или бездействия налоговых органов и их должностных лиц.\n\nПри удовлетворении заявления (жалобы), если для регистрации договора о создании консолидированной группы налогоплательщиков не имеется иных препятствий, установленных настоящей главой, налоговый орган обязан зарегистрировать указанный договор, а указанная группа признается созданной с 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором такая группа подлежала регистрации в соответствии с пунктом 8 настоящей статьи.","article_title":"Статья 25.3. Договор о создании консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"098c1b7b91d9f2459d99ea7cc2c195a5b7a408ad13cf68686fa658ce7cd9cf87"}]$law7d0057$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
